            name: "Чайка",
            price: 200,
            author: {
                name: "Чехов",
                year: 1860
            }
        }, {
            name: "Война и мир",
            price: 230,
            author: {
                name: "Толстой",
                year: 1828
            }
}];
$.ajax({
    url: '/api/values/',
    type: 'POST',
    data: JSON.stringify(books),
    contentType: "application/json;charset=utf-8",
    success: function (data) {
			alert('Данные отправлены');
    }
